#include <string.h>
#define R(x,n) ((x>>n)|(x<<(32u-n)))
static const uint32_t K[64]={
0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};
static uint32_t be32(const unsigned char*p){return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];}
static void put32(unsigned char*p,uint32_t v){p[0]=(unsigned char)(v>>24);p[1]=(unsigned char)(v>>16);p[2]=(unsigned char)(v>>8);p[3]=(unsigned char)v;}
static void transform(TitanSha256Context*c,const unsigned char*b){uint32_t w[64],a,bv,d,e,f,g,h,t1,t2,cc;unsigned i;for(i=0;i<16;i++)w[i]=be32(b+4*i);for(i=16;i<64;i++){uint32_t x=w[i-15],y=w[i-2];uint32_t s0=R(x,7)^R(x,18)^(x>>3),s1=R(y,17)^R(y,19)^(y>>10);w[i]=w[i-16]+s0+w[i-7]+s1;}a=c->state[0];bv=c->state[1];cc=c->state[2];d=c->state[3];e=c->state[4];f=c->state[5];g=c->state[6];h=c->state[7];for(i=0;i<64;i++){uint32_t S1=R(e,6)^R(e,11)^R(e,25),ch=(e&f)^((~e)&g),S0=R(a,2)^R(a,13)^R(a,22),maj=(a&bv)^(a&cc)^(bv&cc);t1=h+S1+ch+K[i]+w[i];t2=S0+maj;h=g;g=f;f=e;e=d+t1;d=cc;cc=bv;bv=a;a=t1+t2;}c->state[0]+=a;c->state[1]+=bv;c->state[2]+=cc;c->state[3]+=d;c->state[4]+=e;c->state[5]+=f;c->state[6]+=g;c->state[7]+=h;}
void TitanSha256_Init(TitanSha256Context*c){static const uint32_t init[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};if(!c)return;memcpy(c->state,init,sizeof(init));c->total=0;c->used=0;}
void TitanSha256_Update(TitanSha256Context*c,const void*data,size_t n){const unsigned char*p=(const unsigned char*)data;if(!c||(!p&&n))return;c->total+=(uint64_t)n;while(n){size_t take=64u-c->used;if(take>n)take=n;memcpy(c->block+c->used,p,take);c->used+=(unsigned int)take;p+=take;n-=take;if(c->used==64u){transform(c,c->block);c->used=0;}}}
void TitanSha256_Final(TitanSha256Context*c,unsigned char out[32]){uint64_t bits;unsigned i;if(!c||!out)return;bits=c->total*8u;c->block[c->used++]=0x80u;if(c->used>56u){while(c->used<64u)c->block[c->used++]=0;transform(c,c->block);c->used=0;}while(c->used<56u)c->block[c->used++]=0;for(i=0;i<8;i++)c->block[63u-i]=(unsigned char)(bits>>(8u*i));transform(c,c->block);for(i=0;i<8;i++)put32(out+4u*i,c->state[i]);memset(c,0,sizeof(*c));}
void TitanSha256_Hex(const unsigned char d[32],char h[65]){static const char x[]="0123456789abcdef";unsigned i;if(!d||!h)return;for(i=0;i<32;i++){h[i*2]=x[d[i]>>4];h[i*2+1]=x[d[i]&15];}h[64]='\0';}
int TitanSha256_HexEqual(const unsigned char d[32],const char*e){char h[65];unsigned i;unsigned diff=0;if(!d||!e||strlen(e)!=64u)return 0;TitanSha256_Hex(d,h);for(i=0;i<64;i++){unsigned char a=(unsigned char)h[i],b=(unsigned char)e[i];if(b>='A'&&b<='F')b=(unsigned char)(b-'A'+'a');diff|=(unsigned)(a^b);}return diff==0u;}
